"""Fixtures were generated by the old runtime at the recorded source_commit.

Each contains an accepted Run and an actual safe-point checkpoint, not hashes
computed using the implementation under test.
"""

import json
from pathlib import Path

import pytest

from sagents.v2.agent.engine import AgentLoopEngine
from sagents.v2.agent.management.contracts import AgentPackageBundle
from sagents.v2.agent.management.store import AgentPackageStore
from sagents.v2.composition.agent_graph import resolve_agent_graph
from sagents.v2.contracts.commands import ResumeRun
from sagents.v2.contracts.errors import SageV2Error
from sagents.v2.contracts.run_state import RunState
from sagents.v2.package.manifest import SageManifest
from sagents.v2.package.manifest.resolver import CompositionResolver, ResolvedSageManifest
from sagents.v2.testing.plugins.scripted_model import ScriptedModelProvider, ScriptedModelStep
from sagents.v2.testing.runtime import ephemeral_runtime
from sagents.v2.tool import InMemoryToolCatalog, InMemoryToolExecutor
from tests.sagents.v2.test_agent_loop_matrix import CONTEXT, completed


ARCHIVES = json.loads((Path(__file__).parent / "fixtures/retired_budget_archives.json").read_text())


@pytest.mark.parametrize("scope", ARCHIVES["cases"])
@pytest.mark.asyncio
async def test_old_package_and_suspended_run_survive_upgrade(tmp_path, scope):
    old = ARCHIVES["cases"][scope]
    bundle = AgentPackageBundle.model_validate(old["bundle"])
    # Whole-package serialization retains archive identity through process restart.
    bundle = AgentPackageBundle.model_validate_json(bundle.model_dump_json())
    assert bundle.content_hash == old["bundle_hash"]
    resolved = CompositionResolver().resolve(bundle.resolved_manifest())
    assert resolved.manifest_hash == old["manifest_hash"]
    budgets = bundle.manifest.agents["main"].budgets
    assert "system_tokens" not in budgets.model_dump()
    assert "protected_recent_tokens" not in budgets.model_json_schema()["properties"]

    # An existing immutable version/ref must remain saveable without a new version.
    store = AgentPackageStore(tmp_path / "packages.sqlite3")
    with store._connect() as db:
        db.execute("INSERT INTO bundles VALUES (?, ?, ?, ?, ?)",
            ("owner", old["bundle_hash"], bundle.manifest.metadata.id,
             bundle.manifest.metadata.version, json.dumps(old["bundle"])))
    loaded = await store.get("owner", old["bundle_hash"])
    assert await store.save("owner", loaded) == old["bundle_hash"]

    parent = SageManifest.model_validate(old["parent"])
    graph = resolve_agent_graph(parent, parent.runtime, {"worker": resolved})
    assert graph.manifest_hash == old["graph"]["manifest_hash"]
    assert AgentPackageBundle(manifest=parent, dependencies={"worker": bundle}).content_hash == old["nested_bundle_hash"]
    archived_graph = ResolvedSageManifest.model_validate(old["graph"])
    assert json.loads(archived_graph.model_dump_json()) == old["graph"]

    runtime = ephemeral_runtime()
    await runtime.session_store.load_state(old["state"])
    run_id = old["state"]["runs"][0]["run_id"]
    run = await runtime.get_run(run_id)
    suspension = await runtime.session_store.get_suspension(run.suspension_id)
    await runtime.resume_run(ResumeRun(
        run_id=run_id, suspension_id=suspension.suspension_id,
        expected_revision=run.revision,
        expected_suspension_revision=suspension.expected_revision,
        idempotency_key="upgraded-resume"), CONTEXT)
    loop = AgentLoopEngine(runtime=runtime,
        model=ScriptedModelProvider((ScriptedModelStep(events=(completed("done"),)),)),
        tool_catalog=InMemoryToolCatalog(()), tool_executor=InMemoryToolExecutor({}, {}),
        expected_resolved_spec_hash=resolved.manifest_hash)
    assert (await loop.resume(run_id, CONTEXT)).state == RunState.COMPLETED


@pytest.mark.parametrize("change", ["instructions", "tools", "budget", "checkpoint"])
@pytest.mark.asyncio
async def test_legacy_identity_does_not_allow_real_composition_changes(change):
    old = ARCHIVES["cases"]["both"]
    data = json.loads(json.dumps(old["bundle"]))
    agent = data["manifest"]["agents"]["main"]
    if change == "instructions":
        agent["instructions"]["inline"] = "Changed instruction"
    elif change == "tools":
        agent["tools"] = ["changed_tool"]
    elif change == "budget":
        agent["budgets"]["input_tokens"] = 1000
    resolved = CompositionResolver().resolve(AgentPackageBundle.model_validate(data).manifest)
    runtime = ephemeral_runtime()
    state = json.loads(json.dumps(old["state"]))
    if change == "checkpoint":
        state["checkpoints"][0]["resolved_spec_hash"] = "sha256:incompatible-checkpoint"
    await runtime.session_store.load_state(state)
    run_id = old["state"]["runs"][0]["run_id"]
    run = await runtime.get_run(run_id)
    suspension = await runtime.session_store.get_suspension(run.suspension_id)
    await runtime.resume_run(ResumeRun(
        run_id=run_id, suspension_id=suspension.suspension_id,
        expected_revision=run.revision,
        expected_suspension_revision=suspension.expected_revision,
        idempotency_key="incompatible-resume"), CONTEXT)
    loop = AgentLoopEngine(runtime=runtime, model=ScriptedModelProvider(()),
        tool_catalog=InMemoryToolCatalog(()), tool_executor=InMemoryToolExecutor({}, {}),
        expected_resolved_spec_hash=resolved.manifest_hash)
    with pytest.raises(SageV2Error) as error:
        await loop.resume(run_id, CONTEXT)
    assert error.value.info.code == "loop.resolved_spec_incompatible"
    assert error.value.info.safe_to_resume is False
